before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
	"fmt"
)

func divide(a, b int) (int, bool) {
	if b == 0 { return 0, false }
	return a / b, true
}

func main() {
	value, ok := divide(8, 2)
	fmt.Println(value, ok)
}

```

